CREATE TABLE "User" ("id" SERIAL NOT NULL,"email" TEXT NOT NULL,"passwordHash" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "User_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "User_email_key" ON "User"("email");
CREATE TABLE "Profile" ("id" SERIAL NOT NULL,"userId" INTEGER NOT NULL,"name" TEXT NOT NULL,"age" INTEGER NOT NULL,"gender" TEXT NOT NULL,"heightCm" DOUBLE PRECISION NOT NULL,"weightKg" DOUBLE PRECISION NOT NULL,"targetWeightKg" DOUBLE PRECISION NOT NULL,"activityLevel" TEXT NOT NULL,CONSTRAINT "Profile_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "Profile_userId_key" ON "Profile"("userId");
CREATE TABLE "FitnessPlan" ("id" SERIAL NOT NULL,"userId" INTEGER NOT NULL,"goal" TEXT NOT NULL,"bmi" DOUBLE PRECISION NOT NULL,"bmr" DOUBLE PRECISION NOT NULL,"tdee" DOUBLE PRECISION NOT NULL,"targetCalories" INTEGER NOT NULL,"proteinG" INTEGER NOT NULL,"carbsG" INTEGER NOT NULL,"fatG" INTEGER NOT NULL,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "FitnessPlan_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "FitnessPlan_userId_key" ON "FitnessPlan"("userId");
CREATE TABLE "WorkoutPlan" ("id" SERIAL NOT NULL,"userId" INTEGER NOT NULL,"dayOfWeek" INTEGER NOT NULL,"title" TEXT NOT NULL,"difficulty" TEXT NOT NULL,"exercises" JSONB NOT NULL,CONSTRAINT "WorkoutPlan_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "WorkoutPlan_userId_dayOfWeek_key" ON "WorkoutPlan"("userId","dayOfWeek");
CREATE TABLE "DietPlan" ("id" SERIAL NOT NULL,"userId" INTEGER NOT NULL,"mealType" TEXT NOT NULL,"items" JSONB NOT NULL,"calories" INTEGER NOT NULL,"proteinG" INTEGER NOT NULL,"carbsG" INTEGER NOT NULL,"fatG" INTEGER NOT NULL,CONSTRAINT "DietPlan_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "DietPlan_userId_mealType_key" ON "DietPlan"("userId","mealType");
CREATE TABLE "WeightLog" ("id" SERIAL NOT NULL,"userId" INTEGER NOT NULL,"date" DATE NOT NULL,"weightKg" DOUBLE PRECISION NOT NULL,CONSTRAINT "WeightLog_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "WeightLog_userId_date_key" ON "WeightLog"("userId","date");
CREATE TABLE "WaterLog" ("id" SERIAL NOT NULL,"userId" INTEGER NOT NULL,"date" DATE NOT NULL,"glasses" INTEGER NOT NULL DEFAULT 0,CONSTRAINT "WaterLog_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "WaterLog_userId_date_key" ON "WaterLog"("userId","date");
CREATE TABLE "SleepLog" ("id" SERIAL NOT NULL,"userId" INTEGER NOT NULL,"date" DATE NOT NULL,"hours" DOUBLE PRECISION NOT NULL,CONSTRAINT "SleepLog_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "SleepLog_userId_date_key" ON "SleepLog"("userId","date");
CREATE TABLE "Reminder" ("id" SERIAL NOT NULL,"userId" INTEGER NOT NULL,"type" TEXT NOT NULL,"label" TEXT NOT NULL,"time" TEXT NOT NULL,"enabled" BOOLEAN NOT NULL DEFAULT true,CONSTRAINT "Reminder_pkey" PRIMARY KEY ("id"));
ALTER TABLE "Profile" ADD CONSTRAINT "Profile_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE;
